                <Bell className="h-12 w-12 text-gray-300 mx-auto mb-2" />
                <p className="text-gray-400 text-sm">No notifications</p>
                <p className="text-gray-300 text-xs mt-1">You're all caught up!</p>
              </div>
            ) : (
